//! Parity tests: validate Rust results against Python hmmlearn fixtures.
//!
//! Fixtures are generated by `tests/generate_fixtures.py` using hmmlearn.
//! These tests load the JSON fixtures and assert numerical parity
//! within defined tolerance tiers.

use hmm_rs::prelude::*;
use ndarray::{Array1, Array2, Array3};
use std::fs;

const SCORE_TOL: f64 = 1e-9;
const POSTERIOR_TOL: f64 = 1e-9;

fn load_fixture(name: &str) -> serde_json::Value {
    let path = format!("tests/fixtures/{}", name);
    let data = fs::read_to_string(&path)
        .unwrap_or_else(|_| panic!("Fixture not found: {}. Run: python3 tests/generate_fixtures.py", path));
    serde_json::from_str(&data).unwrap()
}

fn json_to_array2(val: &serde_json::Value) -> Array2<f64> {
    let rows: Vec<Vec<f64>> = serde_json::from_value(val.clone()).unwrap();
    let nrows = rows.len();
    let ncols = rows[0].len();
    Array2::from_shape_fn((nrows, ncols), |(i, j)| rows[i][j])
}

fn json_to_array1(val: &serde_json::Value) -> Array1<f64> {
    let v: Vec<f64> = serde_json::from_value(val.clone()).unwrap();
    Array1::from_vec(v)
}

fn json_to_array3(val: &serde_json::Value) -> Array3<f64> {
    let data: Vec<Vec<Vec<f64>>> = serde_json::from_value(val.clone()).unwrap();
    let d0 = data.len();
    let d1 = data[0].len();
    let d2 = data[0][0].len();
    Array3::from_shape_fn((d0, d1, d2), |(i, j, k)| data[i][j][k])
}

// ==========================================================================
// CategoricalHMM parity
// ==========================================================================

#[test]
fn test_categorical_score_parity() {
    let fix = load_fixture("categorical.json");

    let mut model = CategoricalHmm::categorical(2);
    model.emission.n_features = Some(fix["n_features"].as_u64().unwrap() as usize);
    model.startprob_ = json_to_array1(&fix["startprob"]);
    model.transmat_ = json_to_array2(&fix["transmat"]);
    model.emission.emissionprob_ = Some(json_to_array2(&fix["emissionprob"]));
    model.fitted = true;

    let x = json_to_array2(&fix["X"]);
    let lengths = [x.nrows()];

    let rust_score = model.score(&x, &lengths).unwrap();
    let py_score = fix["expected"]["score"].as_f64().unwrap();

    assert!(
        (rust_score - py_score).abs() < SCORE_TOL,
        "CategoricalHMM score: Rust={} Python={} diff={}",
        rust_score, py_score, (rust_score - py_score).abs()
    );
}

#[test]
fn test_categorical_decode_parity() {
    let fix = load_fixture("categorical.json");

    let mut model = CategoricalHmm::categorical(2);
    model.emission.n_features = Some(fix["n_features"].as_u64().unwrap() as usize);
    model.startprob_ = json_to_array1(&fix["startprob"]);
    model.transmat_ = json_to_array2(&fix["transmat"]);
    model.emission.emissionprob_ = Some(json_to_array2(&fix["emissionprob"]));
    model.fitted = true;

    let x = json_to_array2(&fix["X"]);
    let lengths = [x.nrows()];

    let (rust_lp, rust_states) = model.decode(&x, &lengths, None).unwrap();
    let py_lp = fix["expected"]["decode_log_prob"].as_f64().unwrap();
    let py_states: Vec<usize> = fix["expected"]["decode_states"]
        .as_array().unwrap()
        .iter().map(|v| v.as_u64().unwrap() as usize)
        .collect();

    assert!(
        (rust_lp - py_lp).abs() < SCORE_TOL,
        "CategoricalHMM decode log_prob: Rust={} Python={}",
        rust_lp, py_lp
    );
    assert_eq!(
        rust_states.as_slice().unwrap(),
        &py_states[..],
        "CategoricalHMM decode states mismatch"
    );
}

#[test]
fn test_categorical_posteriors_parity() {
    let fix = load_fixture("categorical.json");

    let mut model = CategoricalHmm::categorical(2);
    model.emission.n_features = Some(fix["n_features"].as_u64().unwrap() as usize);
    model.startprob_ = json_to_array1(&fix["startprob"]);
    model.transmat_ = json_to_array2(&fix["transmat"]);
    model.emission.emissionprob_ = Some(json_to_array2(&fix["emissionprob"]));
    model.fitted = true;

    let x = json_to_array2(&fix["X"]);
    let lengths = [x.nrows()];

    let rust_post = model.predict_proba(&x, &lengths).unwrap();
    let py_post = json_to_array2(&fix["expected"]["posteriors"]);

    for i in 0..rust_post.nrows() {
        for j in 0..rust_post.ncols() {
            assert!(
                (rust_post[[i, j]] - py_post[[i, j]]).abs() < POSTERIOR_TOL,
                "CategoricalHMM posteriors[{},{}]: Rust={} Python={} diff={}",
                i, j, rust_post[[i, j]], py_post[[i, j]],
                (rust_post[[i, j]] - py_post[[i, j]]).abs()
            );
        }
    }
}

