// ==========================================================================
// GaussianHMM (spherical covariance) parity
// ==========================================================================

#[test]
fn test_gaussian_spherical_score_parity() {
    let fix = load_fixture("gaussian_spherical.json");
    let nc = fix["n_components"].as_u64().unwrap() as usize;
    let nf = fix["n_features"].as_u64().unwrap() as usize;

    let mut model = GaussianHmm::gaussian(nc, CovarianceType::Spherical);
    model.emission.n_features = Some(nf);
    model.startprob_ = json_to_array1(&fix["startprob"]);
    model.transmat_ = json_to_array2(&fix["transmat"]);
    model.emission.means_ = Some(json_to_array2(&fix["means"]));
    // hmmlearn covars_ returns full (nc, nf, nf) matrices; extract scalar variance per component
    let full_covars = json_to_array3(&fix["covars"]);
    let mut sph = Array1::<f64>::zeros(nc);
    for c in 0..nc {
        // Average diagonal (spherical = same variance for all features)
        let mut sum = 0.0;
        for f in 0..nf {
            sum += full_covars[[c, f, f]];
        }
        sph[c] = sum / nf as f64;
    }
    model.emission.covars_spherical_ = Some(sph);
    model.fitted = true;

    let x = json_to_array2(&fix["X"]);
    let lengths = [x.nrows()];

    let rust_score = model.score(&x, &lengths).unwrap();
    let py_score = fix["expected"]["score"].as_f64().unwrap();

    assert!(
        (rust_score - py_score).abs() < SCORE_TOL,
        "GaussianHMM(spherical) score: Rust={} Python={} diff={}",
        rust_score, py_score, (rust_score - py_score).abs()
    );
}

// ==========================================================================
// GaussianHMM (tied covariance) parity
// ==========================================================================

#[test]
fn test_gaussian_tied_score_parity() {
    let fix = load_fixture("gaussian_tied.json");
    let nc = fix["n_components"].as_u64().unwrap() as usize;
    let nf = fix["n_features"].as_u64().unwrap() as usize;

    let mut model = GaussianHmm::gaussian(nc, CovarianceType::Tied);
    model.emission.n_features = Some(nf);
    model.startprob_ = json_to_array1(&fix["startprob"]);
    model.transmat_ = json_to_array2(&fix["transmat"]);
    model.emission.means_ = Some(json_to_array2(&fix["means"]));
    // hmmlearn covars_ returns (nc, nf, nf) for tied; all identical — take first
    let full_covars = json_to_array3(&fix["covars"]);
    model.emission.covars_tied_ = Some(full_covars.index_axis(ndarray::Axis(0), 0).to_owned());
    model.fitted = true;

    let x = json_to_array2(&fix["X"]);
    let lengths = [x.nrows()];

    let rust_score = model.score(&x, &lengths).unwrap();
    let py_score = fix["expected"]["score"].as_f64().unwrap();

    assert!(
        (rust_score - py_score).abs() < SCORE_TOL,
        "GaussianHMM(tied) score: Rust={} Python={} diff={}",
        rust_score, py_score, (rust_score - py_score).abs()
    );
}

